-- Integration tests run in a rolled-back transaction. No users or bookings persist.
begin;
set local plpgsql.check_asserts = on;
do $$
declare
  opt30 uuid; opt60 uuid; opt90 uuid; other60 uuid; couples uuid;
  d date := (clock_timestamp() at time zone 'Africa/Johannesburg')::date+30;
  q jsonb; receipt jsonb; bid uuid; first_id uuid; rid uuid; uid uuid := gen_random_uuid(); sess uuid := gen_random_uuid(); rejected boolean;
begin
  select o.id into opt60 from public.spa_options o join public.spa_services s on s.id=o.service_id where s.name='Swedish Massage' and duration=60;
  select o.id into opt90 from public.spa_options o join public.spa_services s on s.id=o.service_id where s.name='Swedish Massage' and duration=90;
  select o.id into opt30 from public.spa_options o join public.spa_services s on s.id=o.service_id where s.name='Sports Massage' and duration=30;
  select o.id into other60 from public.spa_options o join public.spa_services s on s.id=o.service_id where s.name='Signature Facial' and duration=60;
  select o.id into couples from public.spa_options o join public.spa_services s on s.id=o.service_id where s.name='Couples Retreat' and duration=60;
  assert opt30 is not null and opt60 is not null and opt90 is not null;
  q := public.spa_quote(opt30,d,'10:00',1); assert jsonb_array_length(q->'sessions')=1 and (q->>'total_cents')::int=28000;
  q := public.spa_quote(opt30,d,'09:00',80); assert jsonb_array_length(q->'sessions')=20,'Every group that fits the day is supported';
  q := public.spa_quote(couples,d,'10:00',2); assert (q->>'total_cents')::int=50000 and (q->'sessions'->0->>'people')::int=2;
  rejected:=false; begin perform public.spa_quote(couples,d,'10:00',3); exception when raise_exception then rejected:=true; end; assert rejected,'Odd couples count must fail';
  q := public.spa_quote(opt60,d,'10:00',10);
  assert jsonb_array_length(q->'sessions')=3 and q->'sessions'->0->>'people'='4' and q->'sessions'->2->>'people'='2';
  assert (q->'sessions'->2->>'ends_at')::timestamptz=(d::timestamp+interval '13 hours') at time zone 'Africa/Johannesburg';
  q := public.spa_quote(opt90,d,'10:00',10);
  assert (q->'sessions'->2->>'ends_at')::timestamptz=(d::timestamp+interval '14 hours 30 minutes') at time zone 'Africa/Johannesburg';
  rejected:=false; begin perform public.spa_quote(opt90,d,'18:00',1); exception when raise_exception then rejected:=true; end; assert rejected,'Closing hours';
  rejected:=false; begin perform public.spa_quote(opt60,d,'10:15',1); exception when raise_exception then rejected:=true; end; assert rejected,'Half-hour grid';
  rejected:=false; begin perform public.spa_quote(opt60,d,'18:00',10); exception when raise_exception then rejected:=true; end; assert rejected,'Full group closing hours';
  q := public.spa_quote(opt60,d,'10:00',3); rid:=gen_random_uuid();
  receipt:=public.spa_submit(opt60,d,'10:00',3,'QA rollback customer','0000000000','qa@example.invalid',q->>'quote',rid);
  assert receipt->>'status'='confirmed';
  assert public.spa_submit(opt60,d,'10:00',3,'QA rollback customer','0000000000','qa@example.invalid',q->>'quote',rid)->>'reference'=receipt->>'reference','Idempotent retry';
  rejected:=false; begin perform public.spa_submit(opt60,d,'11:00',3,'QA rollback customer','0000000000','qa@example.invalid','changed',rid); exception when raise_exception then rejected:=true; end; assert rejected,'Changed retry rejected';
  select id into first_id from public.spa_bookings where reference=receipt->>'reference';
  q:=public.spa_quote(other60,d,'10:00',1);assert q->'sessions'->0->>'people'='1','Shared remaining space';
  rejected:=false; begin perform public.spa_quote(other60,d,'10:00',2); exception when raise_exception then rejected:=true; end;assert rejected,'Different services share total capacity';
  rejected:=false; begin perform public.spa_quote(opt60,d,'10:30',2); exception when raise_exception then rejected:=true; end;assert rejected,'Overlap second interval';
  q:=public.spa_quote(other60,d,'10:00',6);assert q->'sessions'->0->>'people'='1' and q->'sessions'->1->>'people'='4' and q->'sessions'->2->>'people'='1','Partially filled group sessions';
  update public.spa_bookings set status='pending',hold_until=clock_timestamp()-interval '1 second' where id=first_id;
  q:=public.spa_quote(other60,d,'10:00',4);assert q->'sessions'->0->>'people'='4','Expiry releases capacity immediately';
  update public.spa_bookings set status='cancelled' where id=first_id;
  q:=public.spa_quote(opt60,d,'10:00',4);assert q->'sessions'->0->>'people'='4','Cancellation releases capacity';
  update public.spa_bookings set status='rejected' where id=first_id;
  q:=public.spa_quote(opt60,d,'10:00',4);assert q->'sessions'->0->>'people'='4','Rejection releases capacity';
  rejected:=false;begin perform public.spa_admin_data();exception when insufficient_privilege then rejected:=true;end;assert rejected,'Anonymous admin data denied';
  rejected:=false;begin perform public.spa_admin_change('settings','{"pending_minutes":5,"preparation_minutes":0}');exception when insufficient_privilege then rejected:=true;end;assert rejected,'Anonymous admin writes denied';
  insert into auth.users(id,email) values(uid,'qa-owner@example.invalid');
  insert into auth.sessions(id,user_id) values(sess,uid);
  insert into public.spa_admins(user_id,role) values(uid,'owner');
  perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated','session_id',sess)::text,true);
  assert public.spa_is_admin(),'Authorised member with live session';
  assert public.spa_admin_data()->'bookings' is not null;
  perform public.spa_admin_change('notes',jsonb_build_object('id',first_id,'notes','Private QA note'));
  assert (select body='Private QA note' from public.spa_notes where booking_id=first_id);
  q:=public.spa_quote(opt60,d,'12:00',4);
  receipt:=public.spa_submit(opt60,d,'12:00',4,'QA admin phone','0000000000','qa@example.invalid',q->>'quote',gen_random_uuid(),'telephone');
  select id into bid from public.spa_bookings where reference=receipt->>'reference';
  perform public.spa_admin_change('status',jsonb_build_object('id',bid,'status','confirmed'));
  assert (select status='confirmed' from public.spa_bookings where id=bid);
  q:=public.spa_admin_change('reschedule_quote',jsonb_build_object('id',bid,'date',d,'time','13:00'));
  perform public.spa_admin_change('reschedule',jsonb_build_object('id',bid,'date',d,'time','13:00','quote',q->>'quote'));
  assert (select min(starts_at)=(d::timestamp+interval '13 hours') at time zone 'Africa/Johannesburg' from public.spa_sessions where booking_id=bid),'Reschedule moves reservation';
  q:=public.spa_quote(opt60,d,'15:00',4);
  receipt:=public.spa_submit(opt60,d,'15:00',4,'QA blocker','0000000000','qa@example.invalid',q->>'quote',gen_random_uuid());
  rejected:=false;begin perform public.spa_admin_change('reschedule',jsonb_build_object('id',bid,'date',d,'time','15:00','quote','stale'));exception when raise_exception then rejected:=true;end;
  assert rejected and (select min(starts_at)=(d::timestamp+interval '13 hours') at time zone 'Africa/Johannesburg' from public.spa_sessions where booking_id=bid),'Failed reschedule preserves original';
  perform public.spa_admin_change('status',jsonb_build_object('id',bid,'status','cancelled'));
  q:=public.spa_quote(other60,d,'13:00',4); assert q is not null;
  perform public.spa_admin_change('settings','{"pending_minutes":30,"preparation_minutes":30}');
  q:=public.spa_quote(opt60,d,'09:00',6);
  assert (q->'sessions'->1->>'starts_at')::timestamptz=(d::timestamp+interval '10 hours 30 minutes') at time zone 'Africa/Johannesburg','Preparation between sessions';
  perform public.spa_admin_change('settings','{"pending_minutes":60,"preparation_minutes":0}');
  perform public.spa_admin_change('block',jsonb_build_object('starts_at',(d::timestamp+interval '9 hours') at time zone 'Africa/Johannesburg','ends_at',(d::timestamp+interval '10 hours') at time zone 'Africa/Johannesburg','reason','QA rollback block'));
  rejected:=false;begin perform public.spa_quote(other60,d,'09:00',1);exception when raise_exception then rejected:=true;end;assert rejected,'Blocked times';
  delete from auth.sessions where id=sess;
  assert not public.spa_is_admin(),'Logout invalidates existing access token';
  rejected:=false;begin perform public.spa_admin_data();exception when insufficient_privilege then rejected:=true;end;assert rejected,'Revoked session denied';
  assert not has_table_privilege('anon','public.spa_bookings','select');
  assert not has_table_privilege('authenticated','public.spa_bookings','insert');
  assert not has_table_privilege('authenticated','public.spa_admins','insert');
end $$;
set local role authenticated;
do $$ begin assert (select count(*)=0 from public.spa_bookings),'RLS denies a revoked staff session'; assert (select count(*)=0 from public.spa_notes),'RLS protects notes'; end $$;
reset role;
rollback;
select 'PASS: individual, couples, 30/60/90 minutes, 10-person groups, partial slots, cross-service capacity, overlaps, closing hours, half-hour starts, expiry, cancellation, rejection, retries, admin permissions, notes, reschedule success and rollback, preparation, blocked times, session revocation and RLS. All fixtures rolled back.' as result;
